  "upgrade.upgradeNeverRestartsTrial": "Kuboresha hakuanzishi kamwe upya jaribio lako la bure.",
  "upgrade.trialHistoryNote": "Ikiwa unalipia Essentials na kuhamia Business, unahifadhi akaunti ile ile ya mteja na historia ya jaribio. Business haijumuishi jaribio la ziada la siku saba. Ikiwa utaboresha wakati jaribio lako la awali bado linaendelea, tarehe yake ya awali ya mwisho haiwekwi upya.",
  "upgrade.providerConfirmNote": "Mabadiliko ya mpango yanahitaji uthibitisho kutoka kwa mtoa huduma wa malipo. Tofauti yoyote ya bei, mgawo wa uwiano, na tarehe ya kuanza kutumika lazima vionyeshwe kabla ya kuidhinisha mabadiliko. Kuboresha hakupaswi kuunda usajili wa pili unaoendelea kwa wakati mmoja.",
  "upgrade.chargedThroughProviderNote": "Mabadiliko ya mpango hutozwa kupitia mtoa huduma wa malipo. Unaweza kughairi usajili wako kutoka ukurasa huu kwa kutumia kitufe cha Ghairi Usajili chini ya mpango wako wa sasa, au kutoka Mipangilio. Kughairi husitisha upyaaji wa baadaye mwishoni mwa kipindi chako ulicholipia; haimalizi kamwe ufikiaji wako mara moja. Maeneo ya kazi ya bure yaliyopo hayatozwi kwa kutazama chaguo hizi.",
  "billing.cancel.title": "Ghairi usajili",
