  "billing.cancel.refundWindowOpen": "Ulighairi ndani ya siku 3 za tozo yako ya kwanza uliyolipia, kwa hivyo unaweza kustahiki kurejeshewa malipo hayo ya kwanza. Kughairi hakutoi urejeshaji wenyewe — uombe kupitia {contact}.",
