  "exports.eyebrow": "Data",
  "exports.title": "Kuhamisha na nakala rudufu",
  "exports.subtitleStart": "Upakuaji huwa unazuiliwa kila wakati kwa",
  "exports.subtitleRest": ". Kila faili huandikwa jina la biashara na tarehe iliyotengenezwa.",
  "exports.createBusinessFirst": "Tengeneza biashara kwanza — usafirishaji ni wa biashara, si wa programu.",
  "exports.lockedTitle": "Usafirishaji wa CSV na Excel ni kipengele cha Business",
  "exports.lockedDesc": "Eneo lako la kazi liko kwenye mpango wa Essentials. Business huongeza usafirishaji wa CSV na Excel, uthamini wa hisa, bidhaa na wafanyakazi wasio na kikomo, wasambazaji, ununuzi na vifurushi.",
  "exports.seeBusiness": "Tazama Business inajumuisha nini",
  "exports.whatTheseAre": "Faili hizi ni nini",
  "exports.about1": "Kila mkusanyiko wa data huja kama CSV au kitabu halisi cha kazi cha Excel (.xlsx) — kitabu kamili cha kazi cha hesabu ni cha Excel pekee, chenye karatasi moja kwa kila mkusanyiko wa data. Faili za CSV hufunguka katika Excel, Numbers, Google Sheets na programu nyingi za hisa. Maandishi ya UTF-8, koma zilizonukuliwa, mipasuko ya mistari katika maelezo na sufuri za mwanzo katika misimbo yote huhifadhiwa, na seli zinazoanza kama fomula hubatilishwa ili lahajedwali izifungue kama maandishi.",
  "exports.about2": "Katika faili za Excel, SKU, UPC, ISBN na misimbopau ni seli za maandishi — kamwe si nukuu ya kisayansi na kamwe si sufuri zilizopunguzwa — huku upana wa safu wima, vichujio vya vichwa na miundo ya sarafu au kiasi ikitumika. Kitabu kamili cha kazi cha hesabu huweka bidhaa, viwango vya hisa, maeneo na mienendo kwenye karatasi tofauti.",
  "exports.about3": "Usafirishaji mkubwa sana husimama katika safu 20,000 kwa kila mkusanyiko wa data — hilo linapotokea jina la faili husema hivyo (truncated-20000), ili faili isiyo kamili isiwahi kuonekana kama kamili.",
  "exports.about4": "Nakala rudufu ni muhtasari wa data yako, si urejeshaji wa kubofya mara moja. Kuirejesha ni kazi ya mikono, ya kukagua kwanza, kwa hivyo weka faili salama — hakuna chochote katika programu kinachoweza kuunda upya biashara iliyofutwa kutoka kwayo bado. Msimbo wa programu na nakala rudufu za jukwaa la Base44 hushughulikiwa kando na faili hizi.",
  "exports.about5": "Picha na viambatisho huorodheshwa kama viungo vyake vilivyohifadhiwa — faili zenyewe za picha hazipakiwa katika upakuaji.",
  "exports.backupTitle": "Nakala rudufu kamili",
  "exports.backupDesc": "Faili moja yenye bidhaa za biashara hii, maeneo, viwango vya hisa, daftari kamili la mienendo, wasambazaji, ununuzi, maagizo, marejesho, hesabu na uorodheshaji — pamoja na mipangilio yake ya wasifu. Iweke mahali unapodhibiti.",
  "exports.backupIncludes1": "Bidhaa, misimbo, gharama na maelezo",
  "exports.backupIncludes2": "Maeneo na kiasi kwa kila eneo",
  "exports.backupIncludes3": "Kila mwendo, pamoja na mtendaji na wakati",
