  "import.createDesc": "huongeza safu ambazo bado haziko katika katalogi. SKU na misimbopau iliyorudiwa ambayo tayari inatumika hurukwa, na hisa ya ufunguzi inaweza kufika katika eneo unalochagua kama risiti.",
  "import.updateTitle": "Sasisha bidhaa zilizopo",
  "import.updateDesc": "huliganisha kila safu kwa SKU au kitambulisho cha rekodi na huonyesha thamani ya zamani kando ya mpya inayopendekezwa. Seli tupu huacha thamani iliyohifadhiwa kama ilivyo isipokuwa ukiomba nafasi tupu zifutwe, na kiasi hakiguswi kamwe.",
  "import.receiveModeTitle": "Pokea hisa",
  "import.receiveModeDesc": "huongeza kiasi kinachofika katika eneo moja na huandika risiti katika daftari la mienendo kwa kila mstari. Kila kundi huwekewa alama, ili karatasi hiyo hiyo isiweze kupokelewa mara mbili.",
  "import.excelNote": "Vitabu vya kazi vya Excel (.xlsx) husomwa moja kwa moja — chagua karatasi ya kazi na safu wima hulinganishwa kwa ajili yako. Misimbo hubaki kamili: UPC iliyohifadhiwa kama maandishi hubaki na tarakimu zake na sufuri za mwanzo. Safu ambazo haziwezi kuingizwa huorodheshwa pamoja na sababu",
