  "reports.movementsCapped": "Maingizo mapya zaidi tu {cap} ya daftari yalisomwa, kwa hivyo mienendo ya zamani kuliko hii haiko katika jumla. Punguza kipindi ili kuona takwimu kamili kwa muda fulani.",
