  "print.selectedProducts": "{label} · bidhaa {count} zimechaguliwa",
  "print.clearSelection": "Futa uteuzi",
  "print.templateIsBusiness": "{label} ni kipengele cha Business",
  "print.supplierBlockedDesc": "Hati za wasambazaji huenda na mpango wa Business — wasambazaji, ununuzi na maagizo ya ununuzi. Kila ulicho nacho sasa kinaendelea kufanya kazi.",
  "print.seeBusiness": "Tazama Business inajumuisha nini",
  "print.nothingToPrint": "Hakuna cha kuchapisha bado",
  "print.pickOrderHint": "Chagua agizo la ununuzi kutoka kwenye orodha ili kuhakiki hati.",
  "print.pickCustomerOrderHint": "Chagua agizo la mteja kutoka kwenye orodha ili kuhakiki hati.",
  "print.pickReturnHint": "Chagua marejesho yaliyorekodiwa kutoka kwenye orodha ili kuhakiki hati.",
  "print.chooseStyleHint": "Chagua mtindo, kisha chagua bidhaa kutoka kwenye orodha. Hakiki huonyesha hasa kinachotoka kwenye kichapishi.",
  "print.howToReach": "Jinsi ya kufikia kichapishi chako",
  "print.howIntro": "Programu hii huunganishwa na vichapishi ambavyo tayari unamiliki — yenyewe si kichapishi. Kuna njia nne za kufikia kimoja, na lebo huchapishwa kwenye mipango yote miwili kupitia yoyote kati yake. Karatasi za kufungashia, maagizo ya ununuzi, hati za wasambazaji na ripoti ni za Business pekee, bila kujali muunganisho.",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "Kutoka ukurasa huu, kwenye Chrome au Edge ya kompyuta na kwenye Chrome ya Android: chagua kichapishi chako cha lebo na lebo huenda moja kwa moja kwake. Haifanyi kazi katika Safari ya iOS — kwenye iPhone, uchapishaji wa Bluetooth huja na programu ya simu badala yake. Kichapishi kinachozungumza tu Zebra ZPL au lugha ya Brother yenyewe hakitaelewa lebo ambazo ukurasa huu hutuma; hiyo huangaliwa dhidi ya vichapishi halisi kabla ya kuitwa inafanya kazi.",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "Sakinisha kichapishi kwenye Wi-Fi ya duka lako, kisha tumia kitufe cha Chapisha — huchapisha kupitia kichapishi kilichosakinishwa kwenye kompyuta hii, kupitia mtandao wa duka. Kwenye iPhone, AirPrint imejengwa ndani: kichapishi cha AirPrint kwenye Wi-Fi hiyo hiyo huonekana tu katika karatasi ya uchapishaji, hakuna waya na hakuna programu inayohitajika, na programu haihitaji msimbo maalum wa AirPrint. Kichapishi lazima kiunge mkono AirPrint (vichapishi vingi vipya hufanya hivyo) na simu na kichapishi lazima viwe kwenye Wi-Fi hiyo hiyo.",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "Unganisha kichapishi kwenye mtandao wa duka lako kwa waya wa Ethernet, kisakinishe kwenye kompyuta, na uchapishe kupitia kitufe cha Chapisha. Ethernet ni njia ya kompyuta — iPhone hazitumii nyaya za Ethernet.",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "Chomeka kichapishi kwenye kompyuta kwa waya wake na utumie kitufe cha Chapisha — huchapisha kupitia kichapishi kilichosakinishwa hapo. Kwenye simu ya Android yenye waya wa USB OTG, kitufe cha USB kilicho hapo juu huzungumza moja kwa moja na kichapishi. iPhone haziwezi kuchapisha kupitia USB moja kwa moja — hakuna WebUSB hapo — kwa hivyo tumia Wi-Fi / AirPrint, au Bluetooth kutoka programu ya simu.",
  "print.howCordsLead": "Nyaya bado huhudumia iPhone, hatua moja mbali.",
  "print.howCordsBody": "Kichapishi cha USB kilichochomekwa kwenye kompyuta ya duka, au kichapishi cha Ethernet kilichounganishwa kwenye mtandao, huonekana kwenye iPhone yako kupitia Wi-Fi ya duka (AirPrint / kichapishi kilichoshirikiwa) — nyaya huweka kichapishi kwenye mtandao kwa uthabiti, na simu hukifikia bila waya.",
  "print.howOfflineLead": "Mtandao ukikatika,",
  "print.howOfflineBody": "lebo na hati ambazo tayari ziko kwenye ukurasa huu bado huchapishwa — kitufe cha Chapisha, PDF ya lebo, Bluetooth na USB hazihitaji muunganisho. Kinachohitaji mtandao ni kupakia ukurasa na bidhaa zake kwanza. Hali kamili ya nje ya mtandao (kufanya kazi katika programu bila muunganisho wowote) ni ujenzi tofauti, mkubwa zaidi na haidaiwi hapa.",
