  "settings.businesses.create": "Unda biashara",
  "settings.businesses.createDescription": "Hii huunda biashara tofauti yenye bidhaa, maeneo, wasambazaji na rekodi zake za ununuzi. Biashara zilizopo hazitabadilishwa. Maeneo ya kazi ya bure ya kabla ya uzinduzi hayaanzishi jaribio jingine la bure.",
