  "settings.cancelSubscription": "Ghairi Usajili",
  "settings.cancelTerms.appleLink": "Maelekezo ya kughairi ya Apple",
  "settings.cancelTerms.googlePlayLink": "Maelekezo ya kughairi ya Google Play",
  "settings.cancelTerms.graceTitle": "Baada ya kipindi chako cha kulipia kuisha — siku 15 za neema, kisha kufutwa:",
  "settings.cancelTerms.intro": "Haya ni masharti ya usajili wa kulipia wa Luminous StockHaven. Bili ya usajili wa tovuti ni kupitia Stripe. Unaweza kughairi usajili wako mwenyewe wakati wowote kwa kutumia kitufe cha Ghairi Usajili kilicho hapa chini — hakuna idhini ya wafanyakazi inayohitajika. Maombi ya kughairi na kurejeshewa fedha yanaweza pia kushughulikiwa kupitia mawasiliano rasmi ya usaidizi kwa wateja, theluminousbookshop@outlook.com.",
  "settings.cancelTerms.noApprovalBody": "Unaweza kughairi usajili wako mwenyewe wakati wowote. Hakuna idhini ya wafanyakazi inayohitajika. Upyaji wa baadaye husimama tu baada ya mtoa huduma wa bili kuthibitisha kughairiwa.",
  "settings.cancelTerms.noApprovalTitle": "Ghairi bila idhini:",
  "settings.cancelTerms.paymentBody": "Kwa majaribio ya kulipia, jaribio la siku saba linahitaji njia ya malipo wakati wa kujisajili. Isipokuwa limeghairiwa ndani ya tarehe ya mwisho inayotumika ya kughairi jaribio, mpango wa kila mwezi uliochaguliwa utatozwa kiotomatiki baada ya jaribio. Bei, tarehe ya kwanza ya bili, na tarehe ya mwisho ya kughairi mahususi kwa mtoa huduma lazima zionyeshwe wakati wa kujisajili. Bili ya jaribio ni kupitia Stripe.",
  "settings.cancelTerms.paymentTitle": "Njia ya malipo na upyaji wa kiotomatiki:",
  "settings.cancelTerms.remainingBody": "Ikiwa tayari umelipia kipindi cha bili, unaweza kuendelea kupata ufikiaji hadi tarehe hiyo iliyothibitishwa ya kulipiwa hadi. Kusitisha mapema kunahitaji uthibitisho unaofaa wa mtoa huduma na ushughulikiaji wowote unaotumika wa kurejeshewa fedha. Ufikiaji wa jaribio la bure huisha kulingana na tarehe ya kusitisha jaribio iliyothibitishwa na mtoa huduma.",
  "settings.cancelTerms.remainingTitle": "Ufikiaji uliobaki:",
  "settings.cancelTerms.storesBody": "Ikiwa utawahi kujisajili kupitia Google Play au Apple App Store, usajili wako hutozwa na kusimamiwa na duka hilo. Huenda ukahitaji kuughairi moja kwa moja katika sehemu ya usajili ya akaunti ile ile ya Google au Apple uliyoitumia kujisajili. Kughairi usajili tofauti wa tovuti, kuondoa programu hii, au kuomba kufutwa kwa akaunti ya Luminous StockHaven hakuughairi kiotomatiki usajili unaotozwa na duka. Angalia risiti yako ya ununuzi ili kuthibitisha ni nani anayekutoza.",
  "settings.cancelTerms.storesTitle": "Usajili wa Google Play na Apple App Store (ikiwa utawahi kujisajili kupitia duka):",
  "settings.cancelTerms.title": "Masharti na Vigezo vya Kughairi",
  "settings.cancelTerms.trialBody": "Jaribio la siku saba linaweza kutumika mara moja tu kwa kila mteja anayestahiki. Kughairi jaribio au usajili hakutoi jaribio jingine; wateja wanaorudi lazima wachague usajili wa kulipia.",
  "settings.cancelTerms.trialTitle": "Jaribio moja la bure:",
  "settings.canceled.endsOn": "Usajili huu umeghairiwa na unaisha tarehe {date}. Unaendelea kuwa na ufikiaji kamili hadi wakati huo.",
  "settings.delete.checking": "Inakagua ombi lililopo la kufutwa…",
  "settings.delete.description": "Omba kuondolewa kwa akaunti yako ya kuingia ya Luminous StockHaven.",
  "settings.delete.dialogDescription": "Hii huomba ukaguzi wa kufutwa kwa akaunti. Haiondoi mara moja kuingia kwako au hesabu yako, na haighairi usajili wowote wa Stripe. Andika {word} ili kuthibitisha kuwa unataka kuwasilisha ombi.",
  "settings.delete.dialogTitle": "Omba Kufutwa kwa Akaunti",
  "settings.delete.enterDelete": "Weka {word} ili kuthibitisha",
  "settings.delete.exportFirst": "Hamisha hesabu yako kwanza ikiwa unahitaji kuweka rekodi zako.",
  "settings.delete.intro": "Kuwasilisha ombi hakufuti mara moja akaunti yako, biashara zako, au hesabu yako. Maombi hukaguliwa kando kabla ya kufutwa kukamilishwa. Ombi hili halighairi usajili wa Stripe au kusimamisha bili ya baadaye; kughairi usajili lazima kushughulikiwe kando kupitia mtoa huduma wa bili.",
  "settings.delete.keepAccount": "Weka Akaunti",
  "settings.delete.noExport": "Essentials haina uhamishaji wa data — andika chochote unachohitaji kabla ya kuomba kufutwa.",
  "settings.delete.notDeleted": "Akaunti yako na data yako hazijafutwa na ombi hili. Bili haijaghairiwa.",
