  "settings.title": "Mipangilio",
  "settings.trial.cancelKeeps": "Kughairi wakati wa jaribio lako huweka siku zako 7 kamili — ufikiaji huisha tarehe {date}, na hutatozwa.",
  "staff.access.noSeatBody": "Akaunti yako haina kiti cha wafanyakazi kwa biashara hii, kwa hivyo hisa zake hubaki zimefungwa. Mwombe mmiliki akuongeze katika Wafanyakazi na majukumu.",
  "staff.access.noSeatTitle": "Biashara hii haikufunguki kwa akaunti yako ya kuingia",
  "staff.access.pendingBody": "Biashara hii ina mwaliko kwa barua pepe yako ambao haujaamilishwa. Mwombe mmiliki aweke hali yako ya wafanyakazi kuwa inafanya kazi. Hakuna kinachoonekana hapa hadi wakati huo.",
  "staff.access.pendingTitle": "Mwaliko wako bado haufanyi kazi",
  "staff.access.signOut": "Toka",
  "staff.access.suspendedBody": "Msimamizi amesitisha akaunti hii ya wafanyakazi kwa biashara inayofanya kazi. Mwombe akuweke tena kuwa unafanya kazi, kisha ingia tena.",
  "staff.access.suspendedTitle": "Ufikiaji wako umesitishwa",
  "staff.addFirst": "Ongeza mfanyakazi wa kwanza",
  "staff.addMember": "Ongeza mfanyakazi",
  "staff.emptyBody": "Ongeza mtu, mpe jukumu na ruhusa zinazoambatana nalo, na ataalikwa kwa barua pepe kuingia katika biashara hii.",
  "staff.emptyTitle": "Hakuna wafanyakazi bado",
  "staff.eyebrow": "Timu",
  "staff.how.p1": "Kila mwanachama ana jukumu na orodha yake ya ruhusa, kwa hivyo unaweza kuanza kutoka kwenye jukumu na kubadilisha kitu kimoja bila kuunda jukumu jipya. Kuhariri jukumu hakuandiki upya wanachama ambao tayari wako nalo — fungua mwanachama ili kutumia tena chaguo-msingi za jukumu lake.",
  "staff.how.p2": "Majukumu maalum ni kipengele cha Business: Essentials hutumia majukumu matano yaliyojengwa ndani (Mmiliki, Meneja, Karani wa hisa, Karani wa mauzo, Mtazamaji).",
  "staff.how.p3": "Mialiko hutumwa kwa barua pepe. Mwanachama anaweza kuingia tu mara tu anapokubali, na kumwondoa mtu kwenye orodha hii hakufuti akaunti yake ya programu.",
  "staff.how.p4": "Duka ni eneo ambalo mtu amekabidhiwa. Limeandikwa kwenye kadi yake; kile anachoweza kufungua bado huamuliwa na jukumu na ruhusa zake.",
  "staff.how.p5": "Ruhusa huamua kile kila mtu anachoweza kufungua: vipengee vya menyu vilivyo nje ya jukumu lake hufichwa, na anwani iliyozuiwa huonyesha ilani ya “haiko kwenye jukumu lako” badala ya ukurasa. Badiliko hutumika wakati ujao mtu huyo anapopakia programu; kusitisha mwanachama humfungia nje kabisa.",
  "staff.how.p6": "Wasimamizi wanaweza kuona na kubadilisha data yote, kusimamia watumiaji wa programu na majukumu, na kamwe hawazuiwi na jukumu la wafanyakazi. Mtu asiye na rekodi ya wafanyakazi — mmiliki wa biashara mpya — huendelea kuwa na ufikiaji kamili.",
  "staff.howTitle": "Jinsi wafanyakazi na majukumu yanavyofanya kazi",
  "staff.limitBadgeLabel": "Wafanyakazi",
