  "payroll.dd.savings": "Akiba (savings)",
  "payroll.dd.steps.body": "1. Unahitaji akaunti ya benki ya biashara inayoweza kutuma malipo ya ACH. 2. Kusanya fomu ya idhini iliyotiwa saini kutoka kwa kila mwanatimu - hundi iliyofutwa husaidia kuthibitisha namba. 3. Tuma malipo ya mishahara siku 2-3 za kazi kabla ya siku ya mshahara ili pesa ifike kwa wakati. 4. Majimbo mengi yanahitaji ridhaa ya maandishi ya mwanatimu. Programu hii hukusanya fomu na kukupitisha katika hatua - kutuma pesa kweli hufanyika kupitia benki yako mwenyewe.",
