  "workforce.messages.help": "Ujumbe wa faragha wa mtu mmoja kwa mmoja na timu yako — hakuna programu nyingine inayohitajika. Watu wawili tu katika mazungumzo wanaweza kuisoma, pamoja na mmiliki wa biashara, anayesimamia duka lake.",
