  "training.track.manager": "Wimbo wa meneja",
  "training.track.managerHelp": "Kwa kuendesha timu siku kwa siku: ratiba, likizo, kazi, hati za mishahara na kufunza wafanyakazi wako.",
  "training.track.owner": "Wimbo wa mmiliki",
  "training.track.ownerHelp": "Kila kitu katika programu, ikiwa ni pamoja na malipo ya mishahara, malipo na sehemu ambazo mmiliki pekee anaweza kuzigusa.",
  "training.track.staff": "Wimbo wa wafanyakazi",
  "training.track.staffHelp": "Zana za kila siku: kuchanganua, saa ya muda, ratiba yako, kisanduku pokezi chako na hati yako ya mshahara.",
  "training.warningSentOn": "Onyo limetumwa {date}",
  "auth.sameEmailNotice": "Tayari una programu yetu kutoka Google Play au App Store? Tumia barua pepe ile ile hapa — ile unayoingia nayo kwenye programu — ili duka lako na hesabu yako vije nawe. Barua pepe tofauti huanzisha duka jipya kabisa, tupu.",
  "settings.deleteConfirmWord": "FUTA",
  "login.cantAccessEmail": "Huwezi kuingia kwenye barua pepe yako?",
  "recovery.title": "Rejesha akaunti yako",
  "recovery.subtitle": "Umepoteza ufikiaji wa barua pepe ambayo akaunti yako iko chini yake? Funguo zako za akiba zinaweza kukurudisha kwenye duka lako.",
  "recovery.remembered": "Umeikumbuka hata hivyo?",
  "recovery.backToLogin": "Rudi kwenye kuingia",
  "recovery.genericError": "Kuna kitu kimekwenda vibaya. Tafadhali jaribu tena.",
