  "rewards.subtitle": "Sema asante kwa zawadi — asilimia ya punguzo, kadi ya zawadi, au chochote unachoeleza.",
  "rewards.title": "Zawadi na motisha",
  "rewards.value.giftCard": "Kadi ya zawadi ya {value}",
  "rewards.value.percentOff": "Punguzo la {percent}% dukani",
  "rewards.void": "Batilisha",
  "rewards.voided": "Zawadi imebatilishwa.",
  "workforce.tab.rewards": "Zawadi",
  "training.lessons.mgr-give-rewards.step1": "Fungua Nguvukazi na uguse Zawadi. Chagua mwanatimu, kisha aina: asilimia ya punguzo dukani, kadi ya zawadi, au kitu kingine unachoeleza kwa maneno yako mwenyewe.",
  "training.lessons.mgr-give-rewards.step2": "Ipe zawadi jina fupi na maelezo ukipenda. Mtu hupata kengele mara moja, na zawadi husubiri katika Zawadi zangu zake ikiwa na msimbo wake mwenyewe.",
  "training.lessons.mgr-give-rewards.step3": "Mpaka, kwa muundo: unazawadia WAFANYAKAZI pekee. Huwezi kujizawadia mwenyewe au meneja mwingine — kumzawadia meneja ni uamuzi wa mmiliki, na programu itakataa waziwazi.",
  "training.lessons.mgr-give-rewards.step4": "Kwenye tili, andika msimbo ambao mwanatimu anakuonyesha na uuweke kuwa umetumika — kila msimbo hufanya kazi mara moja. Unaweza kubatilisha zawadi uliyotoa ikiwa mipango itabadilika; zawadi za mmiliki ni za mmiliki kuzibatilisha.",
  "training.lessons.mgr-give-rewards.title": "Kutoa zawadi kwa wafanyakazi wako",
  "training.lessons.owner-give-rewards.step1": "Zawadi huishi katika Nguvukazi, kwenye kichupo cha Zawadi, na ni za mpango wa Business pekee — kwenye Essentials kichupo huonyesha mlango uliofungwa, ili timu yako iweze kuona kile mpango mkubwa unachobeba.",
  "training.lessons.owner-give-rewards.step2": "Unaweza kumzawadia MTU YEYOTE kwenye timu — wafanyakazi na wasimamizi pia. Chagua mtu, kisha aina: asilimia ya punguzo dukani (asilimia yoyote unayochagua), kadi ya zawadi ya mahali popote, au motisha yoyote unayoeleza kwa maneno yako mwenyewe.",
  "training.lessons.owner-give-rewards.step3": "Zawadi hufika na msimbo wake wa mara moja na hulia kengele ya mtu. Huonyesha msimbo kwenye tili; mmiliki au meneja huuandika kuiweka kuwa imetumika.",
  "training.lessons.owner-give-rewards.step4": "Karatasi ya zawadi iliyochapishwa au iliyoshirikiwa hubeba jina la biashara YAKO pekee — kamwe la programu. Ni asante ya duka lako, si tangazo.",
  "training.lessons.owner-give-rewards.title": "Kutoa zawadi (mpango wa Business)",
  "training.lessons.owner-rewards-oversight.step1": "Meneja wako anaweza kutoa zawadi pia — kwa wafanyakazi pekee. Programu hukataa meneja kujizawadia mwenyewe au meneja mwingine; kumzawadia meneja daima ni uamuzi wako.",
  "training.lessons.owner-rewards-oversight.step2": "Unaona kila zawadi katika biashara katika Historia ya zawadi: nani aliitoa, nani aliipata, na ikiwa iko tayari, imetumika au imebatilishwa. Meneja huona tu zawadi alizotoa na zile alizopokea.",
  "training.lessons.owner-rewards-oversight.step3": "Unaweza kubatilisha zawadi yoyote, ikiwa ni pamoja na ile meneja wako aliyotoa. Meneja anaweza kubatilisha zawadi zake mwenyewe, lakini kamwe zako.",
  "training.lessons.owner-rewards-oversight.step4": "Kila msimbo hufanya kazi mara moja hasa, na zawadi iliyobatilishwa kamwe haiwezi kutumika — historia daima huonyesha zawadi iliishia vipi.",
  "training.lessons.owner-rewards-oversight.title": "Kusimamia zawadi: utoaji wa meneja wako",
  "training.lessons.staff-your-rewards.step1": "Meneja wako au mmiliki anapokupa zawadi, kengele yako hulia. Fungua Nguvukazi na uguse Zawadi kuiona chini ya Zawadi zangu.",
  "training.lessons.staff-your-rewards.step2": "Kila zawadi ina msimbo wake. Uweke kwako — yeyote anayeonyesha msimbo kwenye tili ndiye anayetumia zawadi.",
  "training.lessons.staff-your-rewards.step3": "Kuitumia, onyesha msimbo unaponunua. Mtu kwenye tili huuandika na kuiweka kuwa imetumika — kila msimbo hufanya kazi mara moja hasa.",
  "training.lessons.staff-your-rewards.step4": "Zawadi ni ladha ya mpango wa Business. Ikiwa duka lako haliko kwenye Business, kichupo cha Zawadi huonyesha mlango uliofungwa badala yake — huo ndio mpango, si makosa.",
  "training.lessons.staff-your-rewards.title": "Zawadi zako: kupata msimbo wako na kuutumia",
  "training.module.rewards": "Zawadi na motisha",
