  "pos.events.heldPlanNote": "Baadhi ya mauzo hapa chini yalifika duka hili halikuwa kwenye mpango wa Business. Yalitunzwa salama na hakuna kilichohesabiwa. Sasa duka liko kwenye Business, unaweza kuyahesabu.",
